examples.script:
// The vulnerable code is the SIGALRM handler of sshd's pre-authentication listener.
let exposure := service_exposed(["sshd", "ssh"])
if exposure == "installed" || exposure == "absent"
  // sshd is installed but neither running nor socket-activated.
  return LOW
end
// 'LoginGraceTime 0' removes the vulnerable timeout code path; sshd uses the first value it reads.
let grace := directive_values(["/etc/ssh/sshd_config"], "LoginGraceTime", "first")
if grace != null && size(grace) == 1 && grace[0].matches(r"^0+[sSmMhHdDwW]?$")
  return LOW
elif exposure == "loopback"
  // Only reachable from the host itself.
  return LOW
elif uname != null && uname.machine.matches(r"^(i[3-6]86|armv[5-7]l?)$")
  // Exploitation has been publicly demonstrated against 32-bit glibc systems.
  return HIGH
else
  return MEDIUM
end

// nf_tables can be loaded, built in, or available as an autoloadable module.
let nft := kernel_feature("CONFIG_NF_TABLES", "nf_tables")
if nft == "absent"
  // Kernel built without nf_tables: the vulnerable code is not present.
  return ABSENT
elif nft == null
  // Neither the module list nor the kernel configuration is available.
  return null
elif nft == "disabled" || nft == "blacklisted"
  // A modprobe override prevents the module from being (auto)loaded.
  return LOW
end
// Unprivileged user namespaces are the usual route for unprivileged users to reach nf_tables.
let userns := userns_unprivileged_allowed()
if userns == false
  return LOW
elif userns == true && (nft == "loaded" || nft == "builtin")
  return HIGH
else
  // Only available as a module that is not loaded, or user namespace state unknown.
  return MEDIUM
end

// The vulnerable parser is only reached when the TLS ticket feature is enabled in the daemon's configuration.
let tickets := ini_values("/etc/foo/foo.conf", "tls", "session_tickets")
if tickets == null || size(tickets) == 0
  // Configuration unreadable or option not set: the default is on, but the daemon may use another file.
  return MEDIUM
elif tickets[size(tickets) - 1] == "off"
  // The last assignment wins.
  return LOW
else
  return HIGH
end
